'use strict';

function createTaskBoard() {
  const cards = new Map();
  const order = [];

  const copy = card => ({ ...card, tags: card.tags.slice() });

  function normalize(card) {
    if (!card || typeof card !== 'object' || Array.isArray(card)) throw new TypeError('card must be an object');
    const keys = Object.keys(card);
    if (keys.some(key => !['id', 'title', 'priority', 'tags'].includes(key))) throw new TypeError('unknown card field');
    if (typeof card.id !== 'string' || card.id.trim() === '') throw new TypeError('invalid id');
    if (typeof card.title !== 'string' || card.title.trim() === '') throw new TypeError('invalid title');
    if (!Number.isInteger(card.priority) || card.priority < 1 || card.priority > 5) throw new TypeError('invalid priority');
    if (!Array.isArray(card.tags) || card.tags.some(tag => typeof tag !== 'string')) throw new TypeError('invalid tags');
    return { id: card.id, title: card.title.trim(), priority: card.priority, tags: card.tags.slice() };
  }

  function add(card) {
    const value = normalize(card);
    if (cards.has(value.id)) throw new Error('duplicate id');
    cards.set(value.id, value);
    order.push(value.id);
    return copy(value);
  }

  function get(id) {
    return cards.has(id) ? copy(cards.get(id)) : null;
  }

  function list(offset, limit) {
    if (!Number.isInteger(offset) || offset < 0 || !Number.isInteger(limit) || limit < 0) throw new TypeError('invalid range');
    return order.slice(offset, offset + limit).map(id => cards.get(id));
  }

  function patch(id, changes) {
    if (!changes || typeof changes !== 'object' || Array.isArray(changes)) throw new TypeError('changes must be an object');
    if (Object.keys(changes).some(key => !['title', 'priority', 'tags'].includes(key))) throw new TypeError('unknown change');
    if (!cards.has(id)) return null;
    const current = cards.get(id);
    const candidate = normalize({ ...current, ...changes, id });
    cards.set(id, candidate);
    return copy(candidate);
  }

  function remove(id) {
    if (!cards.delete(id)) return false;
    order.splice(order.indexOf(id), 1);
    return true;
  }

  return { add, get, list, patch, remove };
}

module.exports = { createTaskBoard };

