'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createTaskBoard']);
const { createTaskBoard } = api;

const board = createTaskBoard();
assert.deepStrictEqual(board.list(0, 10), []);
assert.strictEqual(board.get('missing'), null);
assert.strictEqual(board.remove('missing'), false);

const source = { id: 'a', title: '  Alpha  ', priority: 1, tags: ['one'] };
const added = board.add(source);
assert.deepStrictEqual(added, { id: 'a', title: 'Alpha', priority: 1, tags: ['one'] });
assert.notStrictEqual(added, source);
assert.notStrictEqual(added.tags, source.tags);
source.title = 'changed';
source.tags.push('source mutation');
added.title = 'returned mutation';
added.tags.push('returned mutation');
assert.deepStrictEqual(board.get('a'), { id: 'a', title: 'Alpha', priority: 1, tags: ['one'] });

board.add({ id: 'b', title: 'Beta', priority: 5, tags: [] });
board.add({ id: 'c', title: 'Gamma', priority: 3, tags: ['x', 'y'] });
assert.deepStrictEqual(board.list(1, 1), [{ id: 'b', title: 'Beta', priority: 5, tags: [] }]);
assert.deepStrictEqual(board.list(3, 2), []);
assert.deepStrictEqual(board.list(99, 0), []);
const listed = board.list(0, 3);
listed[0].tags.push('leak');
listed.splice(1, 1);
assert.deepStrictEqual(board.list(0, 3).map(card => card.id), ['a', 'b', 'c']);
assert.deepStrictEqual(board.get('a').tags, ['one']);

const changes = { title: '  Updated  ', priority: 4, tags: ['new'] };
const patched = board.patch('b', changes);
assert.deepStrictEqual(patched, { id: 'b', title: 'Updated', priority: 4, tags: ['new'] });
changes.tags.push('leak');
patched.tags.push('leak');
assert.deepStrictEqual(board.get('b'), { id: 'b', title: 'Updated', priority: 4, tags: ['new'] });
assert.deepStrictEqual(board.list(0, 3).map(card => card.id), ['a', 'b', 'c']);
assert.strictEqual(board.patch('unknown', { title: 'Valid' }), null);

assert.throws(() => board.add({ id: 'a', title: 'Again', priority: 2, tags: [] }));
const invalidCards = [
  null,
  [],
  { id: '', title: 'X', priority: 1, tags: [] },
  { id: 'x', title: '   ', priority: 1, tags: [] },
  { id: 'x', title: 'X', priority: 0, tags: [] },
  { id: 'x', title: 'X', priority: 2.5, tags: [] },
  { id: 'x', title: 'X', priority: 6, tags: [] },
  { id: 'x', title: 'X', priority: 1, tags: [1] },
  { id: 'x', title: 'X', priority: 1, tags: [], extra: true }
];
for (const card of invalidCards) assert.throws(() => board.add(card));
assert.throws(() => board.patch('a', { id: 'z' }));
assert.throws(() => board.patch('a', { unknown: 1 }));
assert.throws(() => board.patch('a', { title: '' }));
assert.throws(() => board.patch('a', { priority: NaN }));
assert.throws(() => board.patch('a', { tags: ['ok', 2] }));
assert.deepStrictEqual(board.get('a'), { id: 'a', title: 'Alpha', priority: 1, tags: ['one'] });
for (const args of [[-1, 1], [0.5, 1], [0, -1], [0, 1.5]]) {
  assert.throws(() => board.list(args[0], args[1]));
}
assert.strictEqual(board.remove('b'), true);
assert.strictEqual(board.remove('b'), false);
assert.deepStrictEqual(board.list(0, 10).map(card => card.id), ['a', 'c']);

